export function createRound(e){return{phase:"ready",elapsed:0,settled:0,seconds:e.seconds}}export function resetRound(e){return e.phase="ready",e.elapsed=0,e.settled=0,e}export function freePlay(e){return e.phase="free",e.elapsed=0,e.settled=0,e}export function isOver(e){return e.phase==="finale"||e.phase==="done"}export function canBlow(e){return e.phase==="ready"||e.phase==="playing"||e.phase==="free"}export function timeLeft(e){return Math.max(0,e.seconds-e.elapsed)}export function stepRound(e,t,s,a){const p=t>0?t:0;return e.phase==="ready"?s.blowing?(e.phase="playing","start"):null:e.phase==="playing"?(e.elapsed+=p,e.elapsed>=e.seconds?(e.elapsed=e.seconds,e.settled=0,e.phase=a.finale?"finale":"done",e.phase):null):e.phase==="finale"&&(e.settled+=p,s.finaleDone||e.settled>=a.finaleMax)?(e.phase="done","done"):null}
